From 7835876fb9b7e78cdf3cc84073782e6dbaf40a23 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 00:41:33 +0100
Subject: [PATCH] applets/digital-clock: stack hours and minutes in thin
 vertical panels

In a thin vertical panel the time had to fit on one line, so it shrank
to a barely readable size. When the panel is too thin to show the time
at half its full size, now show hours, minutes and AM/PM on own lines.

BUG: 440096
---
 applets/digital-clock/DigitalClock.qml | 60 +++++++++++++++++++-------
 1 file changed, 45 insertions(+), 15 deletions(-)

diff --git a/applets/digital-clock/DigitalClock.qml b/applets/digital-clock/DigitalClock.qml
index 8c918109d0..53ca72d795 100644
--- a/applets/digital-clock/DigitalClock.qml
+++ b/applets/digital-clock/DigitalClock.qml
@@ -25,6 +25,20 @@ MouseArea {

     property string timeFormat
     property string timeFormatWithSeconds
+    property string stackedTimeFormat
+    property string stackedTimeFormatWithSeconds
+
+    // In a thin vertical panel, show hours, minutes and seconds on separate lines
+    // when the time would otherwise be shown at less than half its full size
+    readonly property bool stackedTime: Plasmoid.formFactor === PlasmaCore.Types.Vertical
+        && main.width < oneLineTimeMetrics.advanceWidth / 2
+
+    readonly property string currentTimeFormat: {
+        if (Plasmoid.configuration.showSeconds === 2) {
+            return stackedTime ? stackedTimeFormatWithSeconds : timeFormatWithSeconds;
+        }
+        return stackedTime ? stackedTimeFormat : timeFormat;
+    }

     // This is quite convoluted in Qt 6:
     // Qt.formatDate with locale only accepts Locale.FormatType as format type,
@@ -431,7 +445,7 @@ MouseArea {
                 }
                 minimumPixelSize: 1

-                text: Qt.locale().toString(clock.dateTime, Plasmoid.configuration.showSeconds === 2 ? main.timeFormatWithSeconds : main.timeFormat)
+                text: Qt.locale().toString(clock.dateTime, main.currentTimeFormat)
                 textFormat: Text.PlainText

                 verticalAlignment: Text.AlignVCenter
@@ -503,6 +517,13 @@ MouseArea {
         textFormat: Text.PlainText
     }

+    // The widest one-line time at the maximum font size
+    TextMetrics {
+        id: oneLineTimeMetrics
+
+        font: fontHelper.font
+    }
+
     FontMetrics {
         id: timeMetrics

@@ -538,17 +559,23 @@ MouseArea {
             hoursFormat = "hh";
         }
         let result = hoursFormat + delimiter + minutes;
+        let result_stacked = hoursFormat + "\n" + minutes;

         let result_sec = result + delimiter + seconds;
+        let result_stacked_sec = result_stacked + "\n" + seconds;

         // add "AM/PM" either if the setting is the default and locale uses it OR if the user unchecked "use 24h format"
         if ((Plasmoid.configuration.use24hFormat === Qt.PartiallyChecked && !uses24hFormatByDefault) || Plasmoid.configuration.use24hFormat === Qt.Unchecked) {
             result += " " + amPm;
             result_sec += " " + amPm;
+            result_stacked += "\n" + amPm;
+            result_stacked_sec += "\n" + amPm;
         }

         timeFormat = result;
         timeFormatWithSeconds = result_sec;
+        stackedTimeFormat = result_stacked;
+        stackedTimeFormatWithSeconds = result_stacked_sec;
         setupLabels();
     }

@@ -596,21 +623,21 @@ MouseArea {
                 maximumWidthNumber = i;
             }
         }
-        // replace all placeholders with the widest number (two digits)
-        const format = (Plasmoid.configuration.showSeconds === 2 ? main.timeFormatWithSeconds : main.timeFormat).replace(/(h+|m+|s+)/g, "" + maximumWidthNumber + maximumWidthNumber); // make sure maximumWidthNumber is formatted as string
-        // build the time string twice, once with an AM time and once with a PM time
-        const date = new Date(2000, 0, 1, 1, 0, 0);
-        const timeAm = Qt.formatTime(date, format);
-        const advanceWidthAm = timeMetrics.advanceWidth(timeAm);
-        date.setHours(13);
-        const timePm = Qt.formatTime(date, format);
-        const advanceWidthPm = timeMetrics.advanceWidth(timePm);
+        const widestTime = (timeFormat) => {
+            // replace all placeholders with the widest number (two digits)
+            const format = timeFormat.replace(/(h+|m+|s+)/g, "" + maximumWidthNumber + maximumWidthNumber); // make sure maximumWidthNumber is formatted as string
+            // build the time string twice, once with an AM time and once with a PM time
+            const date = new Date(2000, 0, 1, 1, 0, 0);
+            const timeAm = Qt.formatTime(date, format);
+            const advanceWidthAm = timeMetrics.advanceWidth(timeAm);
+            date.setHours(13);
+            const timePm = Qt.formatTime(date, format);
+            const advanceWidthPm = timeMetrics.advanceWidth(timePm);
+            return advanceWidthAm > advanceWidthPm ? timeAm : timePm;
+        };
+        oneLineTimeMetrics.text = widestTime(Plasmoid.configuration.showSeconds === 2 ? main.timeFormatWithSeconds : main.timeFormat);
         // set the sizehelper's text to the widest time string
-        if (advanceWidthAm > advanceWidthPm) {
-            sizehelper.text = timeAm;
-        } else {
-            sizehelper.text = timePm;
-        }
+        sizehelper.text = widestTime(main.currentTimeFormat);
         fontHelper.text = sizehelper.text
     }

@@ -648,5 +675,8 @@ MouseArea {

         stateChanged
             .connect(setupLabels);
+
+        stackedTimeChanged
+            .connect(setupLabels);
     }
 }
-- 
